-- public.institution_assign_staff(p_institution_id uuid, p_station_id uuid, p_shift_type_id uuid, p_work_date date, p_staff_id uuid, p_confirm_rules text[])
CREATE OR REPLACE FUNCTION public.institution_assign_staff(p_institution_id uuid, p_station_id uuid, p_shift_type_id uuid, p_work_date date, p_staff_id uuid, p_confirm_rules text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  p    public.institution_staff;
  t    public.institution_shift_types;
  span tstzrange;
  new_id uuid;
  rules text[];
begin
  perform private.assert_access_open();  -- LEAVE1-3
  if p_institution_id is null or not private.is_institution_member(p_institution_id, array['lead', 'planner']) then
    return jsonb_build_object('result', 'rejected');
  end if;
  -- Lock the person: two planners assigning the same person at the same time are serialised here.
  select * into p from public.institution_staff where id = p_staff_id and institution_id = p_institution_id for update;
  -- HD-1 R2: share-lock the shift type, so a concurrent time change waits for this assignment (and then sees it).
  select * into t from public.institution_shift_types where id = p_shift_type_id and institution_id = p_institution_id
    for share;
  -- HD-3a Q3: share-lock the home, so the planning limits cannot change between the rule check and the insert.
  perform 1 from public.institutions where id = p_institution_id for share;
  if p.id is null or t.id is null or p_work_date is null
     or not exists (select 1 from public.institution_stations s where s.id = p_station_id and s.institution_id = p_institution_id) then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('not_found'));
  end if;
  if not p.active then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('staff_inactive'));
  end if;
  if exists (select 1 from public.institution_assignments a where a.staff_id = p.id and a.work_date = p_work_date
             and a.shift_type_id = t.id) then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('already_assigned'));
  end if;
  -- HD-1 R3: refused when the shift touches an absence day (also the night D-1 -> D).
  if exists (select 1 from public.institution_absences a where a.staff_id = p.id
             and daterange(a.starts_on, a.ends_on, '[]')
                 && private.institution_shift_days(p_work_date, t.starts_at, t.ends_at)) then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('staff_absent'));
  end if;
  span := private.institution_shift_span(p_work_date, t.starts_at, t.ends_at);
  if exists (select 1 from public.institution_assignments a
             join public.institution_shift_types o on o.id = a.shift_type_id
             where a.staff_id = p.id and a.work_date between p_work_date - 1 and p_work_date + 1
               and private.institution_shift_span(a.work_date, o.starts_at, o.ends_at) && span) then
    return jsonb_build_object('result', 'invalid', 'problems', jsonb_build_array('staff_overlap'));
  end if;
  -- HD-3a Q3 (FE-123): a planning rule (shift model, rest, days in a row, Pensum) is a warning, not a block. The first
  -- call names the rules and writes nothing; the person who confirms them calls again with p_confirm_rules. The rules
  -- are read again here under the same locks, so a rule that appeared in between is never saved unconfirmed.
  rules := private.institution_rule_breaches(p.id, t.id, p_work_date, null);
  if cardinality(rules) > 0 and not (rules <@ coalesce(p_confirm_rules, '{}'::text[])) then
    return jsonb_build_object('result', 'warning', 'rules', to_jsonb(rules));
  end if;
  insert into public.institution_assignments (institution_id, station_id, shift_type_id, work_date, staff_id, created_by,
                                              override_rules, override_by, override_at)
    values (p_institution_id, p_station_id, t.id, p_work_date, p.id, (select auth.uid()),
            case when cardinality(rules) > 0 then rules end,
            case when cardinality(rules) > 0 then (select auth.uid()) end,
            case when cardinality(rules) > 0 then private.now() end)
    returning id into new_id;
  perform private.institution_audit(p_institution_id, 'institution_assign_staff', 'institution_assignments', new_id,
    jsonb_build_object('staff_id', p.id, 'station_id', p_station_id, 'shift_type_id', t.id, 'work_date', p_work_date,
                       'override_rules', case when cardinality(rules) > 0 then to_jsonb(rules) end));
  return jsonb_build_object('result', 'ok', 'assignment_id', new_id);
end $function$;

revoke all on function public.institution_assign_staff(p_institution_id uuid, p_station_id uuid, p_shift_type_id uuid, p_work_date date, p_staff_id uuid, p_confirm_rules text[]) from public, anon, authenticated, service_role;
grant execute on function public.institution_assign_staff(p_institution_id uuid, p_station_id uuid, p_shift_type_id uuid, p_work_date date, p_staff_id uuid, p_confirm_rules text[]) to authenticated;
grant execute on function public.institution_assign_staff(p_institution_id uuid, p_station_id uuid, p_shift_type_id uuid, p_work_date date, p_staff_id uuid, p_confirm_rules text[]) to service_role;
